#if UNITY_6000_0_OR_NEWER
using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;
namespace Ashfall.Integration.Playable.Bots
{
 internal sealed class R24WardenGeometry
 {
  internal sealed class Bucket {internal R24WardenRecipe.Attachment Parent;internal int Material;internal float End;internal bool Shadows;internal Mesh Mesh;internal string SourceKey;internal readonly List<CombineInstance> Pieces=new List<CombineInstance>();}
  internal R24EnemySourceGeometry Original;internal readonly List<Bucket> Buckets=new List<Bucket>();internal readonly Material[] Materials=new Material[12];readonly List<UnityEngine.Object> resources=new List<UnityEngine.Object>();readonly Dictionary<string,Mesh> primitives=new Dictionary<string,Mesh>();static R24WardenGeometry shared;int owners;bool disposed;
  internal static R24WardenGeometry Acquire(){if(shared==null){var candidate=new R24WardenGeometry();try{candidate.Build();shared=candidate;}catch{candidate.Clear();throw;}}shared.owners++;return shared;}
  internal void Release(){if(disposed)return;if(--owners<=0){if(shared==this)shared=null;Clear();}}
  T Own<T>(T resource)where T:UnityEngine.Object{resources.Add(resource);return resource;}
  static Vector3 G(Vector3 p){return new Vector3(p.x,p.y,-p.z);}internal static Quaternion Rotation(Vector3 godotAxis,float angle){return godotAxis.sqrMagnitude<.0000001f?Quaternion.identity:Quaternion.AngleAxis(-angle*Mathf.Rad2Deg,G(godotAxis));}
  Material Material(string name,Color color,float metal,float rough,float energy=0){var shader=Shader.Find("Universal Render Pipeline/Lit");if(shader==null)throw new InvalidOperationException("Warden requires actual installed URP Lit");var m=Own(new Material(shader));m.name="Warden source "+name;m.SetColor("_BaseColor",R24KestrelAssets.ShaderColor(color));m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",1-rough);if(energy>0){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",R24KestrelAssets.ShaderColor(color*energy));}return m;}
  void Build()
  {
   Materials[0]=Material("armor",new Color(.19f,.24f,.25f),.75f,.38f);Materials[1]=Material("edge",new Color(.48f,.53f,.5f),.8f,.38f);Materials[2]=Material("dark",new Color(.035f,.045f,.05f),.55f,.38f);Materials[3]=Material("warning",new Color(.9f,.52f,.08f),.35f,.38f);Materials[4]=Material("optic",new Color(.18f,.85f,1),.25f,.38f,2.5f);Materials[5]=Material("core",new Color(.08f,.45f,1),.35f,.38f,2.5f);Materials[6]=Material("flash",new Color(1,.65f,.18f),0,.8f,5);Materials[7]=Material("ground marker",new Color(1,.34f,.03f),0,.8f,3);int index=8;foreach(string hex in new[]{"263c40","809392","101b20","8e602b"}){Color color;ColorUtility.TryParseHtmlString("#"+hex,out color);Materials[index++]=Material("industrial "+hex,color,.65f,.62f);}
   Original=R24EnemySourceGeometry.Acquire();foreach(var group in Original.ForVariant(3).Groups)Buckets.Add(new Bucket{Parent=(R24WardenRecipe.Attachment)group.Parent,Material=group.Material,End=group.End,Shadows=group.Shadows!=0,Mesh=group.Mesh,SourceKey=group.Key});
   var lookup=new Dictionary<string,Bucket>();foreach(var spec in R24WardenRecipe.Build()){if(spec.Parent!=R24WardenRecipe.Attachment.Flash&&spec.Parent!=R24WardenRecipe.Attachment.Impact)continue;string key=spec.Parent+"/"+spec.Material+"/"+spec.End+"/"+spec.Shadows;Bucket bucket;if(!lookup.TryGetValue(key,out bucket)){bucket=new Bucket{Parent=spec.Parent,Material=spec.Material,End=spec.End,Shadows=spec.Shadows};lookup.Add(key,bucket);Buckets.Add(bucket);}Vector3 scale=spec.Kind==R24WardenRecipe.Shape.Box||spec.Kind==R24WardenRecipe.Shape.Cylinder?spec.Size:Vector3.one;Quaternion rotation=spec.AlignY.sqrMagnitude>.00000001f?Quaternion.FromToRotation(Vector3.up,G(spec.AlignY.normalized)):Rotation(spec.Axis,spec.Angle);bucket.Pieces.Add(new CombineInstance{mesh=Primitive(spec),transform=Matrix4x4.TRS(G(spec.Position),rotation,scale)});}
   foreach(var bucket in Buckets){if(bucket.Mesh!=null)continue;var mesh=Own(new Mesh());mesh.name="Authored Warden "+bucket.Parent+" material"+bucket.Material+" range"+bucket.End;mesh.indexFormat=IndexFormat.UInt32;mesh.CombineMeshes(bucket.Pieces.ToArray(),true,true,false);mesh.RecalculateBounds();bucket.Mesh=mesh;bucket.Pieces.Clear();}
  }
  Mesh Primitive(R24WardenRecipe.Part spec){string key=spec.Kind+":"+spec.Segments+":"+spec.Rings+":"+spec.Inner+":"+spec.Outer+(spec.Kind==R24WardenRecipe.Shape.Plate?":"+spec.Size.ToString("R"):"");Mesh value;if(primitives.TryGetValue(key,out value))return value;
   if(spec.Kind==R24WardenRecipe.Shape.Box)value=R24KestrelGeometry.Box();else if(spec.Kind==R24WardenRecipe.Shape.Cylinder)value=Cylinder(spec.Segments,spec.Rings);else if(spec.Kind==R24WardenRecipe.Shape.Torus)value=Torus(spec.Inner,spec.Outer,spec.Rings,spec.Segments);else value=Plate(spec.Size);Own(value);primitives.Add(key,value);return value;}
  // Godot SurfaceTool's authored front is clockwise. Reflecting Z alone turns
  // that into Unity's outward CW. NO extra index swap (glTF differs here).
  sealed class Builder
  {
   readonly List<Vector3> v=new List<Vector3>(),n=new List<Vector3>();readonly List<int> ix=new List<int>();
   internal void Triangle(Vector3 a,Vector3 b,Vector3 c,Vector3 na,Vector3 nb,Vector3 nc){if(Vector3.Dot(Vector3.Cross(b-a,c-a),na+nb+nc)>0){var p=b;b=c;c=p;p=nb;nb=nc;nc=p;}int start=v.Count;v.Add(G(a));v.Add(G(b));v.Add(G(c));n.Add(G(na));n.Add(G(nb));n.Add(G(nc));ix.Add(start);ix.Add(start+1);ix.Add(start+2);}
   internal Mesh Mesh(string label){var m=new Mesh();m.name=label;m.indexFormat=IndexFormat.UInt32;m.SetVertices(v);m.SetNormals(n);m.SetTriangles(ix,0);m.RecalculateBounds();return m;}
  }
  static Mesh Cylinder(int segments,int rings){var b=new Builder();for(int i=0;i<segments;i++){float aa=i*Mathf.PI*2/segments,bb=(i+1)*Mathf.PI*2/segments;var na=new Vector3(Mathf.Cos(aa),0,Mathf.Sin(aa));var nb=new Vector3(Mathf.Cos(bb),0,Mathf.Sin(bb));for(int j=0;j<=rings;j++){float y=.5f-j/(float)(rings+1),z=y-1f/(rings+1);Vector3 a=na+Vector3.up*y,c=nb+Vector3.up*y,d=na+Vector3.up*z,e=nb+Vector3.up*z;b.Triangle(a,d,c,na,na,nb);b.Triangle(c,d,e,nb,na,nb);}foreach(float sign in new[]{-1f,1f})b.Triangle(Vector3.up*(sign*.5f),na+Vector3.up*(sign*.5f),nb+Vector3.up*(sign*.5f),Vector3.up*sign,Vector3.up*sign,Vector3.up*sign);}return b.Mesh("Godot source Cylinder "+segments+"x"+rings+" reflected CW");}
  static Mesh Torus(float inner,float outer,int rings,int segments){var b=new Builder();float major=(inner+outer)*.5f,minor=(outer-inner)*.5f;for(int i=0;i<rings;i++)for(int j=0;j<segments;j++){var v=new Vector3[4];var n=new Vector3[4];for(int k=0;k<4;k++){int a=i+(k==1||k==2?1:0),c=j+(k>=2?1:0);float aa=a*Mathf.PI*2/rings,bb=c*Mathf.PI*2/segments;n[k]=new Vector3(Mathf.Cos(aa)*Mathf.Cos(bb),Mathf.Sin(bb),Mathf.Sin(aa)*Mathf.Cos(bb));v[k]=new Vector3(Mathf.Cos(aa)*major,0,Mathf.Sin(aa)*major)+n[k]*minor;}b.Triangle(v[0],v[1],v[2],n[0],n[1],n[2]);b.Triangle(v[0],v[2],v[3],n[0],n[2],n[3]);}return b.Mesh("Godot source Torus "+rings+"x"+segments+" reflected CW");}
  static Mesh Plate(Vector3 size){var b=new Builder();float x=size.x*.5f,y=size.y*.5f,z=size.z*.5f,q=Mathf.Min(x,y)*.24f;var outline=new[]{new Vector2(-x+q,-y),new Vector2(x-q,-y),new Vector2(x,-y+q),new Vector2(x,y-q),new Vector2(x-q,y),new Vector2(-x+q,y),new Vector2(-x,y-q),new Vector2(-x,-y+q)};foreach(float sign in new[]{-1f,1f})for(int i=1;i<7;i++){var normal=Vector3.forward*sign;b.Triangle(new Vector3(outline[0].x,outline[0].y,z*sign),new Vector3(outline[i].x,outline[i].y,z*sign),new Vector3(outline[i+1].x,outline[i+1].y,z*sign),normal,normal,normal);}for(int i=0;i<8;i++){var a=outline[i];var c=outline[(i+1)%8];var normal=new Vector3(c.y-a.y,a.x-c.x,0).normalized;b.Triangle(new Vector3(a.x,a.y,-z),new Vector3(c.x,c.y,-z),new Vector3(c.x,c.y,z),normal,normal,normal);b.Triangle(new Vector3(a.x,a.y,-z),new Vector3(c.x,c.y,z),new Vector3(a.x,a.y,z),normal,normal,normal);}return b.Mesh("Exact source beveled plate28tri reflected CW");}
  void Clear(){if(disposed)return;disposed=true;foreach(var item in resources)if(item!=null)UnityEngine.Object.Destroy(item);resources.Clear();Buckets.Clear();primitives.Clear();if(Original!=null){Original.Release();Original=null;}}
 }
}
#endif
